 v=[("el derecho","o direito","Soa como “el de-RÊ-cho”, com «ch» como «tch».","⚖️"),("la dignidad","a dignidade","Soa como “la dig-ni-DAD”.","🕊️"),("la libertad","a liberdade","Soa como “la li-ber-TAD”.","🕊️"),("la igualdad","a igualdade","Soa como “la i-gual-DAD”.","🤝"),("la vivienda","a moradia","Soa como “la bi-BIEN-da”.","🏠"),("garantizar","garantir","Soa como “ga-ran-ti-SAR”.","🔒")],
